-- Reference catalog only. Run as database operator after Phase 2 migrations.
-- Idempotent: existing shared records remain unchanged. No facility stock.
begin;
create temporary table reference_catalog_import(manufacturer text,catalog_number text,name text,category text,description text,gtin text,reference_source text) on commit drop;
with inserted as (insert into public.manufacturers(name) select distinct on(public.normalize_identity(manufacturer)) manufacturer from reference_catalog_import order by public.normalize_identity(manufacturer) on conflict(normalized_name) do nothing returning id) select count(*) as manufacturers_inserted from inserted;
with inserted as (insert into public.products(manufacturer_id,catalog_number,name,category,description,gtin,reference_source) select m.id,r.catalog_number,r.name,r.category,r.description,r.gtin,r.reference_source from reference_catalog_import r join public.manufacturers m on m.normalized_name=public.normalize_identity(r.manufacturer) on conflict(manufacturer_id,normalized_catalog_number) do nothing returning id) select count(*) as products_inserted, (select count(*) from reference_catalog_import)-count(*) as existing_products_preserved from inserted;
commit;
